using System;using System.IO;using System.Linq;using System.Collections.Generic;using Por.Core;
class Stop:Exception{}
class Input:IGameIoHost{
 public Queue<byte[]> Batches=new Queue<byte[]>();public Queue<byte> Keys=new Queue<byte>();public bool Pending;public List<string> Events;
 public bool KeyPressed{get{return Pending&&Keys.Count>0;}}public byte ReadKey(){if(Keys.Count==0){if(Batches.Count==0)throw new Exception("Unexpected blocking read");foreach(var b in Batches.Dequeue())Keys.Enqueue(b);}byte k=Keys.Dequeue();Events.Add("key:"+k);return k;}
 public void Inject(){if(Keys.Count==0){if(Batches.Count==0)throw new Exception("Menu did not finish");foreach(var b in Batches.Dequeue())Keys.Enqueue(b);}}
 public void SoundCommand(ushort c){}public void SoundSuspend(){}public void Interrupt(byte n,Types.TInterruptRegisters r){}public void Halt(int c){throw new Stop();}public void WriteLine(string m){}public TextWriter OpenDebugLog(string s){throw new NotSupportedException();}
}
class Shot{public short X,Y;public byte[] Pixels;}
class Tests{
 static long checks;static List<Shot> shots=new List<Shot>();static List<string> events=new List<string>();static List<string> chars=new List<string>();static Input io=new Input();static int clears;
 static byte B(int n){return unchecked((byte)n);}static void Yes(bool v,string m){checks++;if(!v)throw new Exception(m);}
 static void Setup(){
  GDVars.zone0=new Types.TGbvmZone0State();GDVars.zone1=new Types.TGbvmZone1();GDVars.zone2=new Types.TZone2();GDVars.zone3=new Types.TZone3();GDVars.map3d=new Types.TGeoMap();GDVars.gbStrings=new Types.TGbStrings();GDVars.gameFont=new Types.TFontArr();GDVars.eclScriptId=1;GDVars.zone0.mapId.lo=2;GDVars.zone0.previousScriptId=1;GDVars.gLocType=C_Area.LOC_3D_MAP;GDVars.gMapX=7;GDVars.gMapY=8;GDVars.gFacing=0;GDVars.companionOn=1;GDVars.stingArg=false;GDVars.debugTraceEnabled=false;GDVars.zone0.savedWalls.menuAnimation=0;GDVars.animData.current=0;
  EclBindings.BindConvertedUnits();for(int i=1;i<=5;i++)GDVars.scriptEntryAddrs[i]=0;EvtKind.Prepare();Explored.Clear();MapNotes.Clear();
  GDVars.video.cellShift=3;GDVars.video.screenShift=3;GDVars.video.maskShift=3;GDVars.video.keyed=true;GDVars.video.colours=16;GDVars.video.RemapColour=PicVga.RemapColour;
  GDVars.video.ShowPic=(x,y,p)=>shots.Add(new Shot{X=x,Y=y,Pixels=p.data.Take(64).ToArray()});GDVars.video.ClearScreen=()=>{clears++;events.Add("clear");};GDVars.video.DrawGlyph=(x,y,c,g)=>chars.Add(x+":"+y+":"+c+":"+g);GDVars.video.WriteChar=(x,y,c,n,g)=>{};GDVars.video.ClearRect=(a,b,c,d)=>events.Add("rect:"+a+":"+b+":"+c+":"+d);TextRend.ReadBiosTicks=()=>0;
  Types.TImgBuf set=null,glyph=null;Blit.AllocPic(8,1,32,0,ref set);Blit.AllocPic(8,1,1,0,ref glyph);for(int i=0;i<set.data.Length;i++)set.data[i]=B((i+i/64)%16);for(int i=0;i<8;i++)set.map[i]=B(17*i);
  GDVars.dsSymbolSetPtrs[4]=set;GDVars.dsCurrent8x8SymbolPtr2=glyph;io=new Input{Events=events,Pending=true};GameIo.Host=io;MenuCore.idleHook=()=>io.Inject();MenuCore.extraKeys="";MenuCore.arrowsToCaller=false;CompTool.EditCharacter=null;shots.Clear();chars.Clear();events.Clear();clears=0;
 }
 static void Keys(params byte[][] batches){io.Batches.Clear();io.Keys.Clear();foreach(var b in batches)io.Batches.Enqueue(b);}
 static byte[] K(char c){return new[]{B(c)};}static byte[] Ext(int c){return new[]{(byte)0,B(c)};}
 static void Main(){Setup();Pixels();Squares();Maps();Kinds();Screens();Notes();Console.WriteLine("CompTool source-derived assertions: "+checks);}
 static byte Expected(byte p,bool dim,int fill,bool noted,bool cursor,int colours){if(cursor){if(p==8)return 15;if(p==7||p==15)return 0;return p;}if(noted&&(p==7||p==15))return colours>=16?(byte)14:(byte)13;if(p==8)return fill!=8?B(fill):dim&&colours>=16?(byte)0:p;if((p==7||p==15)&&dim&&colours>=16)return 8;if(p==7&&!dim&&colours<16)return 15;return p;}
 static void Pixels(){var source=GDVars.dsSymbolSetPtrs[4];var initial=(byte[])source.data.Clone();foreach(int colours in new[]{4,16})foreach(bool dim in new[]{false,true})foreach(bool note in new[]{false,true})foreach(bool cursor in new[]{false,true})for(int fill=0;fill<16;fill++)for(int sym=256;sym<276;sym++){
  GDVars.video.colours=B(colours);shots.Clear();CompTool.ShowSymbol(-2,24,(ushort)sym,dim,B(fill),note,cursor);Yes(shots.Count==1&&shots[0].X==-2&&shots[0].Y==24,"signed coords/direct draw");for(int j=0;j<64;j++)Yes(shots[0].Pixels[j]==Expected(initial[(sym-256)*64+j],dim,fill,note,cursor,colours),"independent simultaneous LUT remap");Yes(source.map.Data.SequenceEqual(GDVars.dsCurrent8x8SymbolPtr2.map.Data)&&!ReferenceEquals(source.map,GDVars.dsCurrent8x8SymbolPtr2.map),"inline map copy not alias");}
  Yes(source.data.SequenceEqual(initial),"source atlas immutable");shots.Clear();GDVars.dsSymbolSetPtrs[4]=null;CompTool.ShowSymbol(0,0,256,false,8,false,false);Yes(shots.Count==0,"nil atlas no draw");GDVars.dsSymbolSetPtrs[4]=source;var glyph=GDVars.dsCurrent8x8SymbolPtr2;GDVars.dsCurrent8x8SymbolPtr2=null;CompTool.ShowSymbol(0,0,256,false,8,false,false);Yes(shots.Count==0,"nil scratch no draw");GDVars.dsCurrent8x8SymbolPtr2=glyph;
  foreach(int colours in new[]{4,16,255}){GDVars.video.colours=B(colours);int[] want=colours>=16?new[]{1,3,4,6,2,5,9}:new[]{3,3,5,15,15,5,15};for(byte k=1;k<=7;k++)Yes(CompTool.KindColour(k)==want[k-1],"exact source event palettes");}
 }
 static void Squares(){Setup();GDVars.gMapX=15;GDVars.gMapY=15;for(int bits=0;bits<16;bits++)foreach(bool visited in new[]{false,true})foreach(bool note in new[]{false,true})foreach(bool cursor in new[]{false,true}){
  GDVars.map3d.wallsNE[2,1]=B(((bits&1)!=0?0xF0:0)+((bits&2)!=0?15:0));GDVars.map3d.wallsSW[2,1]=B(((bits&4)!=0?0x30:0)+((bits&8)!=0?4:0));Explored.Clear();if(visited)Explored.Mark(1,2);MapNotes.SetNote(1,2,1,2,note?"NOTE":"");shots.Clear();CompTool.DrawSquare(1,2,cursor);Yes(shots.Count==1&&shots[0].X==3&&shots[0].Y==5,"cell screen offset");for(int j=0;j<64;j++)Yes(shots[0].Pixels[j]==Expected(B(((bits+4)*64+j+(bits+4))%16),!visited,8,note,cursor,16),"all walls exploration/note/cursor overlays");}
  GDVars.gMapX=1;GDVars.gMapY=2;Explored.Clear();MapNotes.Clear();foreach(byte f in new byte[]{0,2,4,6}){GDVars.gFacing=f;shots.Clear();CompTool.DrawSquare(1,2,false);for(int j=0;j<64;j++)Yes(shots[0].Pixels[j]==Expected(B((j+f/2)%16),true,8,false,false,16),"party arrow overrides all wall bits");}
 }
 static void Maps(){Setup();for(int y=0;y<16;y++)for(int x=0;x<16;x++){GDVars.map3d.wallsNE[y,x]=B(x%2*16+y%2);GDVars.map3d.wallsSW[y,x]=B(x%3*16+y%3);if((x+y)%3==0)Explored.Mark((sbyte)x,(sbyte)y);GDVars.map3d.events[y,x]=B((x+y)%4==0?9:0);}MapNotes.SetNote(1,2,3,4,"FOUND");CompTool.DrawMap();var map=shots.Where(p=>p.X>=2&&p.X<18&&p.Y>=3&&p.Y<19).ToArray();Yes(map.Length==256,"all 256 map cells drawn once row-major");for(int i=0;i<256;i++){int x=i%16,y=i/16;Yes(map[i].X==x+2&&map[i].Y==y+3,"row-major order");int symbol=x%2+(y%2!=0?2:0)+(x%3!=0?4:0)+(y%3!=0?8:0)+4;if(x==7&&y==8)symbol=0;for(int j=0;j<64;j++){byte p=B(j+symbol);Yes(map[i].Pixels[j]==Expected(B(p%16),(x+y)%3!=0,(x+y)%4==0?1:8,x==3&&y==4,false,16),"whole map independent pixels");}}
  Yes(shots.Count(p=>p.X==20&&p.Y==8)==1,"one unknown event legend after prepare");Yes(clears==1,"map clears once");Yes(chars.Contains("20:3:10:"+((int)'B'%64)),"bright legend text position/colour");
 }
 static byte[] I(int n){return new byte[]{0,B(n)};}static byte[] A(int n){return new byte[]{1,B(n),B(n>>8)};}
 static void Kinds(){Setup();var code=new List<byte>();Action<int,byte[][]> op=(n,args)=>{code.Add(B(n));foreach(var a in args)code.AddRange(a);};op(C_Ecl.BIT_AND,new[]{A(C_Gbvm.CELL_EVENT),I(255),A(0x4b00)});op(C_Ecl.ONGOTO,new[]{A(0x4b00),I(8)});var slots=new List<int>();for(int i=0;i<8;i++){slots.Add(code.Count);code.AddRange(new byte[]{2,0,0});}op(C_Ecl.EXIT_SCRIPT,new byte[0][]);
  for(int kind=0;kind<8;kind++){int addr=0x9900+code.Count;code[slots[kind]+1]=B(addr);code[slots[kind]+2]=B(addr>>8);switch(kind){case 2:op(C_Ecl.PRINT,new[]{new byte[]{128,1,0}});break;case 3:op(C_Ecl.DAMAGE,new[]{I(1),I(1),I(4),I(0),I(9)});break;case 4:op(C_Ecl.TREASURE,new[]{I(1),I(0),I(0),I(0),I(0),I(0),I(0),I(255)});break;case 5:op(C_Ecl.RUN_PROGRAM,new[]{I(0)});break;case 6:op(C_Ecl.START_COMBAT,new byte[0][]);break;case 7:op(C_Ecl.NEWECL,new[]{I(2)});break;}op(C_Ecl.EXIT_SCRIPT,new byte[0][]);}
  for(int j=0;j<code.Count;j++)GDVars.zone3[0x9900+j]=code[j];GDVars.scriptEntryAddrs[1]=0x9900;
  int[] ev={0,9,2,3,4,5,6,7};for(int y=0;y<16;y++)for(int x=0;x<16;x++)GDVars.map3d.events[y,x]=B(ev[x%8]);CompTool.DrawMap();for(int kind=1;kind<=7;kind++)Yes(EvtKind.Kind(B(kind==1?9:kind))==kind,"real ECL classifier fixture");var legend=shots.Where(p=>p.X==20&&p.Y>=8&&p.Y<15).ToArray();Yes(legend.Length==7,"every kind appears once ordered in legend");int[] colors={1,3,4,6,2,5,9};for(int k=0;k<7;k++){Yes(legend[k].Y==8+k,"source kind order and row");for(int j=0;j<64;j++)Yes(legend[k].Pixels[j]==Expected(B((j+4)%16),false,colors[k],false,false,16),"legend colour through actual renderer");}
 }
 static void Screens(){Setup();GDVars.companionOn=0;GameIo.Host=null;GDVars.video.ClearScreen=null;CompTool.ToolsMenu();Yes(shots.Count==0&&clears==0,"disabled feature true no-op without hosts");Setup();Keys(K('E'));CompTool.ToolsMenu();Yes(clears==1&&io.Batches.Count==0,"tools exit redraw lifecycle");Setup();Keys(K('C'));bool fail=false;try{CompTool.ToolsMenu();}catch(NotSupportedException){fail=true;}Yes(fail,"missing editor explicit");Setup();int edits=0;CompTool.EditCharacter=()=>{edits++;events.Add("edit");};Keys(K('C'),K('E'));CompTool.ToolsMenu();Yes(edits==1&&clears==2&&events.IndexOf("edit")<events.LastIndexOf("clear"),"editor once then redraw");Setup();Keys(K('M'),K('E'),K('E'));CompTool.ToolsMenu();Yes(clears==3&&io.Batches.Count==0,"tools map return redraw");Setup();GDVars.gLocType=2;io.Pending=false;Keys(K('X'));Yes(!CompTool.OnAreaMap()&&clears==0&&events.Contains("key:88"),"wilderness warning read/pause no area draw");Setup();Keys(K((char)27));CompTool.MapTool();Yes(clears==1&&io.Batches.Count==0,"map Escape exits");}
 static void Notes(){
  Setup();GDVars.gMapX=0;GDVars.gMapY=0;Keys(Ext(C_Keys.LEFT),Ext(C_Keys.UP),Ext(C_Keys.RIGHT),Ext(C_Keys.DOWN),K('W'),K('a'),K('b'),K((char)13),K('E'));CompTool.NotesTool();Yes(MapNotes.Note(1,2,1,1)=="AB"&&MapNotes.Note(1,2,0,0)=="","notes bounded moves write real input uppercase");Yes(GDVars.gMapX==0&&GDVars.gMapY==0,"cursor never moves party");Yes(shots.Count(p=>p.X>=2&&p.X<18&&p.Y>=3&&p.Y<19)==256+1+9,"stationary arrows do not restore old square");
  Setup();GDVars.gMapX=15;GDVars.gMapY=15;MapNotes.SetNote(1,2,15,15,"OLD");Keys(Ext(C_Keys.RIGHT),Ext(C_Keys.DOWN),K('W'),K((char)13),K('E'));CompTool.NotesTool();Yes(MapNotes.Note(1,2,15,15)=="OLD","right/down clamp and empty input retains old note");
  Setup();MapNotes.SetNote(1,2,7,8,"OLD");Keys(K('C'),K('E'));CompTool.NotesTool();Yes(MapNotes.Note(1,2,7,8)=="","clear note real storage");
  Setup();for(int i=0;i<128;i++)MapNotes.SetNote(99,1,(sbyte)(i%16),(sbyte)(i/16),"FULL");Keys(K('W'),K('X'),K((char)13),K((char)13),K('E'));CompTool.NotesTool();Yes(MapNotes.Note(1,2,7,8)==""&&events.Count(x=>x=="key:13")==2,"full notes prompt and no write");
 }
